public interface OrderRepository extends JpaRepository<Order, Long> {

    // Solution 1: JOIN FETCH in JPQL — one query with a JOIN
    @org.springframework.data.jpa.repository.Query(
        "SELECT o FROM Order o JOIN FETCH o.customer")
    java.util.List<Order> findAllWithCustomer();

    // Solution 2: @EntityGraph — Spring generates the JOIN for you
    @org.springframework.data.jpa.repository.EntityGraph(attributePaths = {"customer"})
    java.util.List<Order> findAll();
}
// Solution 3: @BatchSize(size = 10) on the collection batches N into N/10 queries
