import jakarta.persistence.*;
import java.util.*;
import org.springframework.data.jpa.repository.*;

@Entity
public class Order {
    @Id @GeneratedValue private Long id;

    @OneToMany(mappedBy = "order", fetch = FetchType.LAZY) // stays lazy
    private List<OrderItem> items = new ArrayList<>();
}

public interface OrderRepository extends JpaRepository<Order, Long> {

    @EntityGraph(attributePaths = {"items"})              // eager just here
    List<Order> findAll();

    @EntityGraph(attributePaths = {"items", "items.product"}) // nested path
    Optional<Order> findById(Long id);
}
// Each annotated call runs a single SQL query with JOINs — no N+1.
