import org.springframework.data.jpa.repository.*;

public interface OrderRepository extends JpaRepository<Order, Long> {
    // Loads orders only; items are lazy -> N+1 when accessed in a loop
    @Query("SELECT o FROM Order o WHERE o.status = :status")
    java.util.List<Order> findByStatusBad(@Param("status") String status);

    // A plain JOIN filters but does NOT populate items -> still N+1
    @Query("SELECT o FROM Order o JOIN o.items i WHERE o.status = :status")
    java.util.List<Order> findByStatusStillBad(@Param("status") String status);
}
